    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split into core version and pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            prerelease_tuple = tuple(identifiers)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def compare_prerelease(pre1, pre2):
        # If both are None, they're equal
        if pre1 is None and pre2 is None:
            return 0
        # Version without pre-release sorts after version with pre-release
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all compared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def compare_versions(v1, v2):
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        # Compare MAJOR.MINOR.PATCH
        if parsed1[:3] != parsed2[:3]:
            if parsed1[:3] < parsed2[:3]:
                return -1
            else:
                return 1

        # Same core version, compare pre-release
        cmp = compare_prerelease(parsed1[3], parsed2[3])
        return cmp

    # Use stable sort to maintain input order for equal versions
    from functools import cmp_to_key
    return sorted(versions, key=cmp_to_key(compare_versions))

